export const ROLES=['Administrador','Ventas','Logística'];
export const AREAS=[
 ['inicio','Resumen','home','GENERAL'],['catalogo','Catálogo y disponibilidad','sparkles','GENERAL'],
 ['clientes','Clientes','users','COMERCIAL'],['cotizaciones','Cotizaciones','file','COMERCIAL'],['reservas','Reservas activas','calendar','COMERCIAL'],['pagos','Pagos y saldos','chart','COMERCIAL'],
 ['productos','Productos e inventario','box','OPERACIONES'],['hojas','Hojas de eventos','clipboard','OPERACIONES'],['salidas','Salidas','out','OPERACIONES'],['entradas','Entradas','in','OPERACIONES'],['incidencias','Incidencias','alert','OPERACIONES'],
 ['usuarios','Usuarios y roles','shield','ADMINISTRACIÓN'],['reportes','Reportes','chart','ADMINISTRACIÓN'],['auditoria','Bitácora','clock','ADMINISTRACIÓN'],['permisos','Probar permisos','key','PROTOTIPO']
];
const rules={Ventas:{inicio:'r',catalogo:'r',clientes:'rw',cotizaciones:'rw',reservas:'rw',pagos:'rw',permisos:'r'},'Logística':{inicio:'r',catalogo:'r',productos:'rw',hojas:'rw',salidas:'rw',entradas:'rw',incidencias:'rw',permisos:'r'}};
export function allowed(role,area,write=false){if(!ROLES.includes(role)||!AREAS.some(x=>x[0]===area))return false;return role==='Administrador'||!!rules[role]?.[area]?.includes(write?'w':'r')}
export function permissionLabel(role,area){return !allowed(role,area)?'Sin acceso':allowed(role,area,true)?'Gestionar':'Consultar'}
export const money=n=>'L '+Number(n).toLocaleString('es-HN',{minimumFractionDigits:2,maximumFractionDigits:2});
export const activeStatus=s=>['CONFIRMADA','EN_PREPARACION','DESPACHADA'].includes(s);
function initialData(){return {version:1,products:[
 {id:'P01',name:'Castillo de colores',category:'Inflables',description:'Saltos, risas y mucha diversión. Ideal de 3 a 10 años.',price:1800,stock:3,maintenance:0,art:'castle',tone:'#f0e9d9'},
 {id:'P02',name:'Resbaladero aventura',category:'Inflables',description:'Un favorito para celebrar al aire libre.',price:2400,stock:2,maintenance:1,art:'slide',tone:'#e5ede4'},
 {id:'P03',name:'Set de mesas infantiles',category:'Mobiliario',description:'Mesa y seis sillas, del tamaño de su imaginación.',price:450,stock:8,maintenance:0,art:'table',tone:'#eee9e3'},
 {id:'P04',name:'Piscina de pelotas',category:'Juegos',description:'Un espacio suave y colorido para los más pequeños.',price:1500,stock:2,maintenance:0,art:'pool',tone:'#e5eced'},
 {id:'P05',name:'Animación Pon Pon',category:'Personal',description:'Juegos guiados y actividades para una fiesta especial.',price:1200,stock:4,maintenance:0,art:'party',tone:'#f3e9df'},
 {id:'P06',name:'Arco de bienvenida',category:'Decoración',description:'El primer gran momento de cada celebración.',price:950,stock:3,maintenance:0,art:'arch',tone:'#ecebdf'}
 ],clients:[{id:'C01',name:'María López',phone:'9999-0101',address:'Col. Miraflores, Tegucigalpa'},{id:'C02',name:'Carlos Mejía',phone:'9999-0102',address:'Residencial Las Uvas, Tegucigalpa'},{id:'C03',name:'Ana Rivera',phone:'9999-0103',address:'Col. Kennedy, Tegucigalpa'}],
 quotes:[{id:'COT-001',clientId:'C01',title:'Cumpleaños de Sofía',date:'2026-11-03',start:'14:00',end:'18:00',productId:'P01',quantity:1,total:1800,deposit:900,status:'CONFIRMADA',staff:'Daniela · Animadora / José · Chofer',address:'Col. Miraflores, Tegucigalpa'},
 {id:'COT-002',clientId:'C02',title:'Celebración de Mateo',date:'2026-11-04',start:'13:00',end:'17:00',productId:'P04',quantity:1,total:1500,deposit:750,status:'EN_PREPARACION',staff:'Lucía · Animadora / Luis · Chofer',address:'Residencial Las Uvas, Tegucigalpa'},
 {id:'COT-003',clientId:'C03',title:'Una tarde de aventuras',date:'2026-11-06',start:'15:00',end:'19:00',productId:'P02',quantity:1,total:2400,deposit:0,status:'COTIZACION',staff:'',address:'Col. Kennedy, Tegucigalpa'}],
 movements:[],incidents:[{id:'INC-001',productId:'P02',note:'Revisión de costura lateral en una unidad.',state:'En reparación',closed:false}],
 users:[{id:'U01',name:'Cuenta Administrador',role:'Administrador',active:true},{id:'U02',name:'Cuenta Ventas',role:'Ventas',active:true},{id:'U03',name:'Cuenta Logística',role:'Logística',active:true}],
 logs:[{id:'B01',role:'Ventas',message:'Reserva confirmada · Cumpleaños de Sofía',time:'Datos de ejemplo'},{id:'B02',role:'Logística',message:'Hoja preparada · Celebración de Mateo',time:'Datos de ejemplo'},{id:'B03',role:'Administrador',message:'Catálogo disponible para el equipo',time:'Datos de ejemplo'}]}}
export const OUT_CONDITIONS=['Buen estado','Desgaste leve (utilizable)','Reparado (utilizable)'];
export const IN_CONDITIONS=[...OUT_CONDITIONS,'Requiere lavado','Requiere reparación menor','Daño grave (casi inutilizable)','Inutilizable'];
export const severe=c=>['Daño grave (casi inutilizable)','Inutilizable'].includes(c);
export const itemsOf=q=>q.items||[{productId:q.productId,quantity:q.quantity,unitPrice:q.total/q.quantity}];
export const balance=q=>Math.max(0,Math.round((q.total-q.deposit)*100)/100);
export const paymentHistory=q=>q.payments|| (q.deposit>0?[{id:'ANT-'+q.id,amount:q.deposit,time:'Registro anterior',note:'Anticipo registrado previamente',role:'Registro anterior'}]:[]);
export const unitsOf=q=>itemsOf(q).reduce((n,i)=>n+i.quantity,0);
const id=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const text=v=>typeof v==='string'&&v.trim().length>0;
const legacy=c=>({Disponible:'Buen estado','En lavado':'Requiere lavado','En reparación':'Requiere reparación menor',Entregado:'Estado no registrado (versión anterior)'}[c]||c||'Estado no registrado (versión anterior)');
export function assigned(q){if(Array.isArray(q.animators))return {animators:q.animators,driver:q.driver||''};const parts=(q.staff||'').split('/');return {animators:parts.length===2?[parts[0].replace(/·.*$/,'').trim()].filter(Boolean):[],driver:parts.length===2?parts[1].replace(/·.*$/,'').trim():''}}
export function migrate(input){
 if(!input||![1,2].includes(input.version))throw Error('Versión de datos no compatible.');
 const d=structuredClone(input);d.care??=[];for(const q of d.quotes)q.payments=paymentHistory(q);
 for(const p of d.products){p.active??=true;p.priceReady??=true;p.image??='';}
 for(const q of d.quotes)q.items=itemsOf(q).map(i=>{const p=d.products.find(p=>p.id===i.productId);return {...i,name:i.name||p?.name||i.productId,unitPrice:i.unitPrice??p?.price??0}});
 for(const m of d.movements){const q=d.quotes.find(q=>q.id===m.quoteId);m.items??=[{productId:m.productId,name:d.products.find(p=>p.id===m.productId)?.name||m.productId,quantity:m.quantity,condition:legacy(m.condition),note:m.note||''}];m.note??='';m.event??={title:q?.title||m.quoteId,date:q?.date||'',start:q?.start||'',end:q?.end||'',address:q?.address||'',client:d.clients.find(c=>c.id===q?.clientId)?.name||'',staff:q?.staff||'No registrado',role:'Registro anterior'};}
 if(d.version===1){d.care.push(...d.incidents.filter(i=>!severe(i.state)).map(i=>({...i,state:legacy(i.state),quantity:i.quantity||1})));d.incidents=d.incidents.filter(i=>severe(i.state));}
 d.version=2;return d;
}
export function seed(){return migrate(initialData());}
const amount=(q,p)=>itemsOf(q).filter(i=>i.productId===p).reduce((n,i)=>n+i.quantity,0);
export function freeUnits(d,pid,date,start,end,exclude){const p=d.products.find(p=>p.id===pid);if(!p?.active)return 0;const qs=d.quotes.filter(q=>q.id!==exclude&&q.date===date&&activeStatus(q.status)&&q.start<end&&q.end>start),points=[start,...qs.map(q=>q.start).filter(t=>t>start&&t<end)];const peak=Math.max(0,...points.map(t=>qs.filter(q=>q.start<=t&&q.end>t).reduce((n,q)=>n+amount(q,pid),0)));return Math.max(0,p.stock-p.maintenance-peak);}
function committed(d,pid){const qs=d.quotes.filter(q=>activeStatus(q.status));return Math.max(0,qs.filter(q=>q.status==='DESPACHADA').reduce((n,q)=>n+amount(q,pid),0),...qs.map(q=>qs.filter(o=>o.date===q.date&&o.start<=q.start&&o.end>q.start).reduce((n,o)=>n+amount(o,pid),0)));}
export function mutate(data,role,action,payload={}){const draft=structuredClone(data),result=apply(draft,role,action,payload);if(action==='reset')return result;Object.assign(data,draft);return result;}
function apply(d,role,action,a){
 const routes={editClient:'clientes',payment:'pagos',client:'clientes',quote:'cotizaciones',confirm:'reservas',staff:'hojas',dispatch:'salidas',return:'entradas',incident:'incidencias',resolve:'incidencias',resolveCare:'productos',product:'productos',adjustStock:'productos',archiveProduct:'productos',restoreProduct:'productos',price:'productos',user:'usuarios',toggleUser:'usuarios',reset:'usuarios'};
 if(!routes[action]||!allowed(role,routes[action],true))throw Error('Acceso denegado. Este rol no puede realizar la operación.');
 if(['price','reset','toggleUser','user'].includes(action)&&role!=='Administrador')throw Error('Esta operación requiere el rol Administrador.');
 const product=pid=>{const p=d.products.find(p=>p.id===pid);if(!p)throw Error('Producto no encontrado.');return p;};
 const quote=()=>{const q=d.quotes.find(q=>q.id===a.id);if(!q)throw Error('Cotización no encontrada.');return q;};let result,message;
 if(action==='client'){if(!text(a.name)||!text(a.phone))throw Error('Completa el nombre y teléfono.');result={id:id('CLI'),name:a.name.trim(),phone:a.phone.trim(),address:a.address?.trim()||''};d.clients.push(result);message='Cliente registrado · '+result.name;}
 if(action==='editClient'){const c=d.clients.find(c=>c.id===a.id);if(!c||!text(a.name)||!text(a.phone))throw Error('Completa nombre y teléfono del cliente.');const before={name:c.name,phone:c.phone,address:c.address||''};c.name=a.name.trim();c.phone=a.phone.trim();c.address=a.address?.trim()||'';result=c;message='Cliente actualizado · '+c.id+' · '+JSON.stringify(before)+' → '+JSON.stringify({name:c.name,phone:c.phone,address:c.address});}
 if(action==='payment'){const q=quote(),amount=Number(a.amount),cents=Math.round(amount*100),remaining=Math.round(balance(q)*100);if(q.status==='COTIZACION')throw Error('Registra primero el anticipo para confirmar la reserva.');if(!Number.isFinite(amount)||amount<=0||Math.abs(amount*100-cents)>0.000001||cents>remaining)throw Error('El abono debe ser mayor a cero, tener hasta dos decimales y no superar el saldo pendiente.');q.payments=paymentHistory(q);const payment={id:id('PAG'),amount:cents/100,time:new Date().toISOString(),note:a.note?.trim()||'',role};q.payments.push(payment);q.deposit=(Math.round(q.deposit*100)+cents)/100;result=payment;message='Pago registrado · '+q.title+' · '+money(payment.amount)+' · Saldo: '+money(balance(q));}
 if(action==='quote'){
  const c=d.clients.find(c=>c.id===a.clientId);if(!c||!text(a.title)||!/^\d{4}-\d{2}-\d{2}$/.test(a.date)||!/^\d{2}:\d{2}$/.test(a.start)||!/^\d{2}:\d{2}$/.test(a.end)||a.end<=a.start)throw Error('Revisa cliente, fecha y horario. La hora final debe ser posterior a la inicial.');
  if(!Array.isArray(a.items)||!a.items.length)throw Error('Añade al menos un producto a la cotización.');const map=new Map();
  for(const line of a.items){const p=product(line.productId),qty=Number(line.quantity);if(!p.active||!p.priceReady)throw Error(p.name+': no está habilitado para cotizar.');if(!Number.isInteger(qty)||qty<1)throw Error('Cada cantidad debe ser un entero mayor a cero.');const i=map.get(p.id)||{productId:p.id,name:p.name,quantity:0,unitPrice:p.price};i.quantity+=qty;map.set(p.id,i);}
  const items=[...map.values()];for(const i of items){const p=product(i.productId);if(i.quantity>p.stock-p.maintenance)throw Error(p.name+': la cantidad supera las unidades operativas.');}
  result={id:id('COT'),title:a.title.trim(),clientId:c.id,date:a.date,start:a.start,end:a.end,items,total:Math.round(items.reduce((n,i)=>n+i.quantity*i.unitPrice,0)*100)/100,deposit:0,status:'COTIZACION',staff:'',address:a.address?.trim()||c.address};d.quotes.unshift(result);message='Cotización creada · '+result.title;
 }
 if(action==='confirm'){const q=quote(),deposit=Number(a.deposit);if(q.status!=='COTIZACION')throw Error('Solo una cotización puede convertirse en reserva.');if(!Number.isFinite(deposit)||deposit<=0||deposit>q.total)throw Error('El anticipo debe ser mayor a cero y no superar el total.');for(const i of itemsOf(q))if(freeUnits(d,i.productId,q.date,q.start,q.end,q.id)<i.quantity)throw Error('Traslape o inventario insuficiente: '+i.name+'.');if(Math.abs(deposit*100-Math.round(deposit*100))>0.000001)throw Error('Usa hasta dos decimales.');q.payments=[{id:id('PAG'),amount:deposit,time:new Date().toISOString(),note:deposit===q.total?'Pago completo inicial':'Anticipo inicial',role}];q.deposit=deposit;q.status='CONFIRMADA';result=q;message='Reserva confirmada · '+q.title;}
 if(action==='staff'){const q=quote(),animators=Array.isArray(a.animators)?a.animators.map(n=>String(n).trim()).filter(Boolean):[],driver=typeof a.driver==='string'?a.driver.trim():'';if(!['CONFIRMADA','EN_PREPARACION'].includes(q.status)||!animators.length||!driver)throw Error('Asigna individualmente al menos un animador y un chofer.');if(new Set(animators.map(n=>n.toLocaleLowerCase())).size!==animators.length)throw Error('No repitas el mismo animador.');q.animators=animators;q.driver=driver;q.staff='Animadores: '+animators.join(', ')+' / Chofer: '+driver;q.status='EN_PREPARACION';result=q;message='Responsables asignados · '+q.title+' · '+q.staff;}
 if(action==='dispatch'||action==='return'){
  const q=quote(),out=action==='dispatch';if(out&&!['CONFIRMADA','EN_PREPARACION'].includes(q.status))throw Error('La reserva no está pendiente de salida.');if(!out&&q.status!=='DESPACHADA')throw Error('Solo se puede recibir un evento despachado.');if(out&&!q.staff)throw Error('Asigna animadora y chofer antes del despacho.');
  if(!Array.isArray(a.items)||!a.items.length)throw Error('Registra el estado de todos los productos.');const expected=new Map(itemsOf(q).map(i=>[i.productId,i.quantity])),counts=new Map(),departure=d.movements.find(m=>m.quoteId===q.id&&m.type==='SA');
  const items=a.items.map(row=>{const p=product(row.productId),quantity=Number(row.quantity);if(!expected.has(p.id)||!Number.isInteger(quantity)||quantity<1||!(out?OUT_CONDITIONS:IN_CONDITIONS).includes(row.condition))throw Error('Revisa productos, cantidades y estados.');if(severe(row.condition)&&!text(row.note))throw Error('Describe el daño grave en las observaciones del producto.');counts.set(p.id,(counts.get(p.id)||0)+quantity);return {productId:p.id,name:p.name,quantity,condition:row.condition,note:row.note?.trim()||'',departureCondition:out?'':[...new Set(departure?.items.filter(i=>i.productId===p.id).map(i=>i.condition)||[])].join(' / ')||'No registrado'};});
  if([...expected].some(([p,n])=>counts.get(p)!==n))throw Error('Las cantidades deben coincidir con todos los productos de la reserva.');
  if(out)for(const i of itemsOf(q)){const p=product(i.productId),away=d.quotes.filter(o=>o.id!==q.id&&o.status==='DESPACHADA').reduce((n,o)=>n+amount(o,p.id),0);if(!p.active||p.stock-p.maintenance-away<i.quantity)throw Error('No hay suficientes unidades operativas en bodega de '+p.name+'.');}
  q.status=out?'DESPACHADA':'FINALIZADA';result={id:id(out?'SA':'EN'),quoteId:q.id,type:out?'SA':'EN',items,quantity:items.reduce((n,i)=>n+i.quantity,0),note:a.note?.trim()||'',time:new Date().toISOString(),event:{title:q.title,date:q.date,start:q.start,end:q.end,address:q.address,client:d.clients.find(c=>c.id===q.clientId)?.name||'',staff:q.staff,animators:assigned(q).animators,driver:assigned(q).driver,role}};d.movements.unshift(result);
  if(!out)for(const i of items)if(['Requiere lavado','Requiere reparación menor'].includes(i.condition)||severe(i.condition)){product(i.productId).maintenance+=i.quantity;(severe(i.condition)?d.incidents:d.care).unshift({id:id(severe(i.condition)?'INC':'MAN'),productId:i.productId,quantity:i.quantity,note:i.note||'Revisión posterior a '+q.title,state:i.condition,closed:false,movementId:result.id});}
  message=(out?'Salida registrada · ':'Entrada registrada · ')+q.title;
 }
 if(action==='incident'){const p=product(a.productId),quantity=Number(a.quantity);if(!p.active||!text(a.note)||!severe(a.state)||!Number.isInteger(quantity)||quantity<1)throw Error('Las incidencias son únicamente para daños graves o productos inutilizables. Describe el daño.');if(quantity>p.stock-p.maintenance-committed(d,p.id))throw Error('Las unidades están comprometidas en reservas activas.');p.maintenance+=quantity;result={id:id('INC'),productId:p.id,note:a.note.trim(),quantity,state:a.state,closed:false};d.incidents.unshift(result);message='Incidencia grave · '+p.name;}
 if(action==='resolve'||action==='resolveCare'){const r=(action==='resolve'?d.incidents:d.care).find(x=>x.id===a.id);if(!r||r.closed)throw Error('El registro ya fue resuelto.');const p=product(r.productId);p.maintenance=Math.max(0,p.maintenance-(r.quantity||1));r.closed=true;result=r;message='Unidades disponibles · '+p.name;}
 if(action==='product'){const price=role==='Administrador'?Number(a.price):0,stock=Number(a.stock);if(!text(a.name)||!text(a.category)||!Number.isFinite(price)||price<0||!Number.isInteger(stock)||stock<1||a.image&&(!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(a.image)||a.image.length>900000))throw Error('Completa nombre, categoría, existencias e imagen válidos.');if(d.products.some(p=>p.active&&p.name.toLocaleLowerCase()===a.name.trim().toLocaleLowerCase()))throw Error('Ya existe este producto. Usa Ajustar unidades.');result={id:id('PRO'),name:a.name.trim(),category:a.category,description:a.description?.trim()||'Producto del catálogo Pon Pon.',price,priceReady:role==='Administrador',stock,maintenance:0,active:true,image:a.image||'',art:{Inflables:'castle',Mobiliario:'table',Juegos:'pool',Personal:'party','Decoración':'arch'}[a.category]||'party',tone:'#ecebdf'};d.products.unshift(result);message='Producto creado · '+result.name;}
 if(action==='price'){const p=product(a.id),price=Number(a.price);if(!Number.isFinite(price)||price<0)throw Error('Indica un precio válido.');p.price=price;p.priceReady=true;result=p;message='Precio definido · '+p.name;}
 if(action==='adjustStock'){const p=product(a.id),delta=Number(a.delta);if(!p.active||!Number.isInteger(delta)||delta===0||!text(a.note))throw Error('Indica una cantidad entera y el motivo del ajuste.');if(p.stock+delta<p.maintenance+committed(d,p.id))throw Error('No puedes retirar unidades comprometidas en reservas, mantenimiento o incidencias.');p.stock+=delta;result=p;message='Inventario ajustado · '+p.name+' · '+(delta>0?'+':'')+delta+' · '+a.note.trim();}
 if(action==='archiveProduct'||action==='restoreProduct'){const p=product(a.id);if(action==='archiveProduct'&&!text(a.note))throw Error('Indica el motivo de eliminación para la bitácora.');if(action==='archiveProduct'&&(committed(d,p.id)>0||p.maintenance>0))throw Error('Resuelve primero las reservas, el mantenimiento o las incidencias.');p.active=action==='restoreProduct';result=p;message=(p.active?'Producto reactivado · ':'Producto eliminado del catálogo · ')+p.name+' · '+p.id+(action==='archiveProduct'?' · Motivo: '+a.note.trim():'');}
 if(action==='user'){if(!text(a.name)||!ROLES.includes(a.role))throw Error('Completa nombre y rol válido.');result={id:id('USR'),name:a.name.trim(),role:a.role,active:true};d.users.push(result);message='Usuario creado · '+result.name;}
 if(action==='toggleUser'){const u=d.users.find(x=>x.id===a.id);if(!u||u.role==='Administrador')throw Error('La cuenta principal debe permanecer activa.');u.active=!u.active;result=u;message='Estado actualizado · '+u.name;}
 if(action==='reset')return seed();
 d.logs.unshift({id:id('BIT'),role,message,time:new Date().toISOString()});return result;
}
